window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e9ab2446a04ba2bc"]={"versions": [{"id": "FIG-e9ab2446a04ba2bc", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst acht AUTOSAR-Pakete sowie ein erläuterndes Notiz-Element:</p>\n<ul class=\"fig-list\"><li><code>GenericStructure</code>: Basispaket für querschnittliche Metamodell-Konzepte. Eine Notiz spezifiziert normativ: „All other top-level packages aggregate meta-classes from &#x27;Generic Structure&#x27;“.\n</li><li><code>CommonStructure</code>: Zentrales Infrastrukturpaket mit Basistypen und gemeinsamen Strukturdefinitionen.\n</li><li><code>SWComponentTemplate</code>: Spezifikation von Software-Komponenten, Ports, Interfaces und internem Verhalten.\n</li><li><code>ECUResourceTemplate</code>: Beschreibung der Hardware-Ressourcen eines Steuergeräts (Mikrocontroller, Speicher, Peripherie).\n</li><li><code>SystemTemplate</code>: Gesamtsystembeschreibung, Netzwerktopologie, Software-Composition und Signal-Mapping.\n</li><li><code>ECUCDescriptionTemplate</code>: ECU-Konfigurationsbeschreibung (konkrete Parameterwerte).\n</li><li><code>ECUCParameterDefTemplate</code>: Definitionsschema für ECU-Konfigurationsparameter.\n</li><li><code>BswModuleTemplate</code>: Spezifikation von Basissoftware-Modulen (BSW).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Paketabhängigkeiten (gestrichelte Pfeile für Metamodell-Importe):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>ECUResourceTemplate</code> (bidirektionale Abhängigkeit).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektionale Abhängigkeit).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die gerichteten Abhängigkeiten sind für AUTOSAR-Autorensysteme, Generatoren und Modell-Validatoren bindend: Ein Paket darf ausschließlich Metaklassen aus Paketen importieren und instanziieren, zu denen ein expliziter Abhängigkeitspfad deklariert ist. Zirkuläre Paketkopplungen bedingen enge syntaktische und semantische Kopplungen zwischen den beteiligten Spezifikationsteilen. Werkzeuge zur XML-/ARXML-Schemagenerierung müssen sicherstellen, dass die globalen Basisklassen aus <code>GenericStructure</code> gemäß der Spezifikationsnotiz allen Top-Level-Paketen zur Aggregation zur Verfügung stehen.</p>"}, {"id": "FIG-9d1badab658f118a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst acht AUTOSAR-Pakete sowie ein erläuterndes Notiz-Element:</p>\n<ul class=\"fig-list\"><li><code>GenericStructure</code>: Basispaket für querschnittliche Metamodell-Konzepte. Eine Notiz spezifiziert normativ: „All other top-level packages aggregate meta-classes from &#x27;Generic Structure&#x27;“.\n</li><li><code>CommonStructure</code>: Zentrales Infrastrukturpaket mit Basistypen und gemeinsamen Strukturdefinitionen.\n</li><li><code>SWComponentTemplate</code>: Spezifikation von Software-Komponenten, Ports, Interfaces und internem Verhalten.\n</li><li><code>ECUResourceTemplate</code>: Beschreibung der Hardware-Ressourcen eines Steuergeräts (Mikrocontroller, Speicher, Peripherie).\n</li><li><code>SystemTemplate</code>: Gesamtsystembeschreibung, Netzwerktopologie, Software-Composition und Signal-Mapping.\n</li><li><code>ECUCDescriptionTemplate</code>: ECU-Konfigurationsbeschreibung (konkrete Parameterwerte).\n</li><li><code>ECUCParameterDefTemplate</code>: Definitionsschema für ECU-Konfigurationsparameter.\n</li><li><code>BswModuleTemplate</code>: Spezifikation von Basissoftware-Modulen (BSW).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Paketabhängigkeiten (gestrichelte Pfeile für Metamodell-Importe):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>ECUResourceTemplate</code> (bidirektionale Abhängigkeit).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektionale Abhängigkeit).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die gerichteten Abhängigkeiten sind für AUTOSAR-Autorensysteme, Generatoren und Modell-Validatoren bindend: Ein Paket darf ausschließlich Metaklassen aus Paketen importieren und instanziieren, zu denen ein expliziter Abhängigkeitspfad deklariert ist. Zirkuläre Paketkopplungen bedingen enge syntaktische und semantische Kopplungen zwischen den beteiligten Spezifikationsteilen. Werkzeuge zur XML-/ARXML-Schemagenerierung müssen sicherstellen, dass die globalen Basisklassen aus <code>GenericStructure</code> gemäß der Spezifikationsnotiz allen Top-Level-Paketen zur Aggregation zur Verfügung stehen.</p>"}, {"id": "FIG-216d8bb8228b7e97", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst zwölf AUTOSAR-Pakete sowie zwei erläuternde Notiz-Elemente:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code>: Paket mit dem Wurzelelement <code>AUTOSAR</code>. Eine zugeordnete Notiz spezifiziert: „This package contains AUTOSAR, the root of an autosar model. It aggregates metaclasses from the template packages.“\n</li><li><code>GenericStructure</code>: Basispaket mit querschnittlichen Metaklassen; Notiz: „All other top-level packages aggregate meta-classes from &#x27;Generic Structure&#x27;“.\n</li><li><code>CommonStructure</code>: Zentrales Paket für plattformweite Typen und Basiskonzepte.\n</li><li><code>StandardizationTemplate</code>: Paket zur Beschreibung standardisierter AUTOSAR-Elemente und Schnittstellenkataloge (isoliertes Basispaket).\n</li><li><code>FeatureModelTemplate</code>: Paket zur Modellierung von Merkmalen und Variabilitäten (isoliertes Basispaket).\n</li><li><code>SWComponentTemplate</code>: Modellierung von Anwendungskomponenten und Schnittstellen.\n</li><li><code>EcuResourceTemplate</code>: Modellierung der Hardware-Ressourcen (Schreibweise camelCase mit kleinem &#x27;cu&#x27;).\n</li><li><code>DiagnosticExtract</code>: Spezifikation von Diagnose-Extraktionen und Services.\n</li><li><code>SystemTemplate</code>: Modellierung der Systemtopologie, Netzwerke und Mappings.\n</li><li><code>ECUCDescriptionTemplate</code>: Instanziierte ECU-Konfigurationen.\n</li><li><code>ECUCParameterDefTemplate</code>: Schemadefinitionen für ECU-Parameter.\n</li><li><code>BswModuleTemplate</code>: Basissoftware-Modulbeschreibungen.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Metamodell-Importe (gestrichelte Pfeile):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>EcuResourceTemplate</code> (bidirektional).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> &lt;---&gt; <code>CommonStructure</code> (bidirektionaler Import).\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektional).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Import-Beziehungen binden Werkzeug- und Schemageneratoren strikt an die deklarierten Paketpfade. Das Wurzelelement <code>AUTOSAR</code> aus <code>AutosarTopLevelStructure</code> dient Modellverarbeitern als eindeutiger Einstiegspunkt zur Aggregation sämtlicher Template-Metaklassen. <code>DiagnosticExtract</code> ermöglicht eine entkoppelte Extraktion diagnoserelevanter Daten direkt aus Software-Komponenten- und Systembeschreibungen. Werkzeuge müssen die gegenseitigen Abhängigkeiten zwischen <code>SystemTemplate</code> und <code>CommonStructure</code> sowie zwischen <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code> bzw. <code>SWComponentTemplate</code> und <code>EcuResourceTemplate</code> konsistent validieren. Die Basispakete <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> stehen ohne explizite Pfeilbeziehungen als referenzierbare Metamodell-Bausteine bereit.</p>"}, {"id": "FIG-f696b1aba3c07875", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst 13 AUTOSAR-Pakete sowie zwei erläuternde Notiz-Elemente:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zum Root-Element <code>AUTOSAR</code>).\n</li><li><code>GenericStructure</code> (mit Notiz zur universellen Aggregation).\n</li><li><code>CommonStructure</code>.\n</li><li><code>StandardizationTemplate</code>.\n</li><li><code>FeatureModelTemplate</code>.\n</li><li><code>SWComponentTemplate</code>.\n</li><li><code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code>: Spezifikation der AUTOSAR Adaptive Platform (Dienste, Plattform-Manifeste, adaptive Anwendungen).\n</li><li><code>DiagnosticExtract</code>.\n</li><li><code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code>.\n</li><li><code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Metamodell-Importe (gestrichelte Pfeile):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>EcuResourceTemplate</code> (bidirektional).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> &lt;---&gt; <code>CommonStructure</code> (bidirektional).\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektional).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Durch die Einbindung von <code>AdaptivePlatform</code> in die Metamodell-Topologie müssen Modellierungswerkzeuge und Validatoren die gemeinsame Nutzung von Basiskonzepten über Plattformgrenzen hinweg unterstützen: <code>AdaptivePlatform</code> darf Metaklassen aus <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code> und <code>SystemTemplate</code> importieren. Damit können Adaptive-Anwendungen und Dienstbeschreibungen direkt an Systemtopologie, Hardware-Ressourcen und komponentenbasierte Softwarearchitekturen angebunden werden, ohne dass eine Rückwärtskopplung der Classic-Templates auf <code>AdaptivePlatform</code> zulässig ist.</p>"}, {"id": "FIG-4e397706d674eae0", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst 13 AUTOSAR-Pakete sowie zwei erläuternde Notiz-Elemente:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zum Root-Element <code>AUTOSAR</code>).\n</li><li><code>GenericStructure</code> (mit Notiz zur universellen Aggregation).\n</li><li><code>CommonStructure</code>.\n</li><li><code>StandardizationTemplate</code>.\n</li><li><code>FeatureModelTemplate</code>.\n</li><li><code>SWComponentTemplate</code>.\n</li><li><code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code>: Spezifikation der AUTOSAR Adaptive Platform (Dienste, Plattform-Manifeste, adaptive Anwendungen).\n</li><li><code>DiagnosticExtract</code>.\n</li><li><code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code>.\n</li><li><code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Metamodell-Importe (gestrichelte Pfeile):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>EcuResourceTemplate</code> (bidirektional).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> &lt;---&gt; <code>CommonStructure</code> (bidirektional).\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektional).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Durch die Einbindung von <code>AdaptivePlatform</code> in die Metamodell-Topologie müssen Modellierungswerkzeuge und Validatoren die gemeinsame Nutzung von Basiskonzepten über Plattformgrenzen hinweg unterstützen: <code>AdaptivePlatform</code> darf Metaklassen aus <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code> und <code>SystemTemplate</code> importieren. Damit können Adaptive-Anwendungen und Dienstbeschreibungen direkt an Systemtopologie, Hardware-Ressourcen und komponentenbasierte Softwarearchitekturen angebunden werden, ohne dass eine Rückwärtskopplung der Classic-Templates auf <code>AdaptivePlatform</code> zulässig ist.</p>"}, {"id": "FIG-48f991b2048a3033", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst 13 AUTOSAR-Pakete sowie zwei erläuternde Notiz-Elemente:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zum Root-Element <code>AUTOSAR</code>).\n</li><li><code>GenericStructure</code> (mit Notiz zur universellen Aggregation).\n</li><li><code>CommonStructure</code>.\n</li><li><code>StandardizationTemplate</code>.\n</li><li><code>FeatureModelTemplate</code>.\n</li><li><code>SWComponentTemplate</code>.\n</li><li><code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code>: Spezifikation der AUTOSAR Adaptive Platform (Dienste, Plattform-Manifeste, adaptive Anwendungen).\n</li><li><code>DiagnosticExtract</code>.\n</li><li><code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code>.\n</li><li><code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Metamodell-Importe (gestrichelte Pfeile):</p>\n<ul class=\"fig-list\"><li><code>SWComponentTemplate</code> &lt;---&gt; <code>EcuResourceTemplate</code> (bidirektional).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> &lt;---&gt; <code>CommonStructure</code> (bidirektional).\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektional).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Durch die Einbindung von <code>AdaptivePlatform</code> in die Metamodell-Topologie müssen Modellierungswerkzeuge und Validatoren die gemeinsame Nutzung von Basiskonzepten über Plattformgrenzen hinweg unterstützen: <code>AdaptivePlatform</code> darf Metaklassen aus <code>SWComponentTemplate</code>, <code>EcuResourceTemplate</code> und <code>SystemTemplate</code> importieren. Damit können Adaptive-Anwendungen und Dienstbeschreibungen direkt an Systemtopologie, Hardware-Ressourcen und komponentenbasierte Softwarearchitekturen angebunden werden, ohne dass eine Rückwärtskopplung der Classic-Templates auf <code>AdaptivePlatform</code> zulässig ist.</p>"}, {"id": "FIG-f65f97fe60602feb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paketdiagramm zur Darstellung der architektonischen Paketstruktur und der Metamodell-Abhängigkeiten (Top-Level-Paketübersicht) innerhalb des AUTOSAR-Standards. Das Diagramm spezifiziert die modulare Gliederung der AUTOSAR-Templates und definiert über gerichtete Import-Beziehungen, welche Template-Pakete Metaklassen aus anderen Paketen referenzieren und einbinden dürfen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst 14 AUTOSAR-Pakete sowie zwei Notiz-Elemente:</p>\n<ul class=\"fig-list\"><li><code>AutosarTopLevelStructure</code> (mit Notiz zum Root-Element <code>AUTOSAR</code>).\n</li><li><code>GenericStructure</code> (mit Notiz zur Aggregation von Metaklassen).\n</li><li><code>CommonStructure</code>.\n</li><li><code>AbstractPlatform</code>: Plattformübergreifendes Abstraktionspaket für Basiskonzepte und gemeinsame Modellierungselemente.\n</li><li><code>StandardizationTemplate</code>.\n</li><li><code>FeatureModelTemplate</code>.\n</li><li><code>SWComponentTemplate</code>.\n</li><li><code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code>.\n</li><li><code>DiagnosticExtract</code>.\n</li><li><code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code>.\n</li><li><code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und gerichtete Metamodell-Importe (gestrichelte Pfeile):</p>\n<ul class=\"fig-list\"><li><code>AbstractPlatform</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SWComponentTemplate</code> &lt;---&gt; <code>EcuResourceTemplate</code> (bidirektional).\n</li><li><code>SWComponentTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>SystemTemplate</code> &lt;---&gt; <code>CommonStructure</code> (bidirektional).\n</li><li><code>SystemTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>SystemTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>DiagnosticExtract</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SystemTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>ECUCDescriptionTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> &lt;---&gt; <code>BswModuleTemplate</code> (bidirektional).\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>EcuResourceTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>ECUCParameterDefTemplate</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> ---&gt; <code>SWComponentTemplate</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Paket- und Metamodell-Strukturdiagramm zeigt das Diagramm keine Laufzeitsequenzen oder zeitliche Dynamik. Der Verarbeitungs- und Entwurfsworkflow verläuft methodisch kaskadierend über die definierten Importpfade: Ausgehend von Basistypen (<code>CommonStructure</code>, <code>GenericStructure</code>) werden Softwarekomponenten (<code>SWComponentTemplate</code>) und Hardwarestrukturen (<code>ECUResourceTemplate</code>) definiert, im <code>SystemTemplate</code> zu Gesamtsystem und Topologie verknüpft, bevor im nachgelagerten Schritt über <code>BswModuleTemplate</code>, <code>ECUCParameterDefTemplate</code> und <code>ECUCDescriptionTemplate</code> die steuergerätespezifische BSW-Konfiguration und Parametrisierung erfolgt. Metamodell-Zyklen (z. B. zwischen <code>SWComponentTemplate</code> und <code>ECUResourceTemplate</code> sowie <code>ECUCDescriptionTemplate</code> und <code>BswModuleTemplate</code>) erfordern eine iterative bzw. wechselseitige Auflösung von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Mit <code>AbstractPlatform</code> wird ein Metamodell-Paket eingeführt, das Metaklassen aus <code>SWComponentTemplate</code> importiert. Werkzeuge müssen sicherstellen, dass die generischen Abstraktionen von Plattformen auf das komponentenbasierte Softwaremodell aufsetzen können, während <code>AbstractPlatform</code> selbst modular als separates Top-Level-Paket geführt wird. Die übrigen Import- und Validierungsregeln bleiben unverändert bestehen.</p>"}], "trans": [{"from": "FIG-e9ab2446a04ba2bc", "to": "FIG-9d1badab658f118a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9d1badab658f118a", "to": "FIG-216d8bb8228b7e97", "fr": "R3.2.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Package <code>ECUResourceTemplate</code> umbenannt in <code>EcuResourceTemplate</code>.\n</li><li>Packages <code>AutosarTopLevelStructure</code>, <code>DiagnosticExtract</code>, <code>StandardizationTemplate</code> und <code>FeatureModelTemplate</code> hinzugefügt.\n</li><li>Annotation / Kommentar zu <code>AutosarTopLevelStructure</code> ergänzt: „This package contains AUTOSAR, the root of an autosar model. It aggregates metaclasses from the template packages.“\n</li><li>Neue Import-Abhängigkeiten eingefügt:\n<ul class=\"fig-list\"><li><code>DiagnosticExtract</code> importiert <code>SWComponentTemplate</code> und <code>SystemTemplate</code>.\n</li><li><code>CommonStructure</code> importiert <code>SystemTemplate</code>.\n</li><li><code>SystemTemplate</code> importiert <code>CommonStructure</code>.\n</li><li><code>BswModuleTemplate</code> importiert <code>CommonStructure</code>.\n</li><li><code>ECUCDescriptionTemplate</code> importiert <code>CommonStructure</code> (über <code>EcuResourceTemplate</code>-Pfadführung entflochten).\n</li></ul>\n</li><li>Geändertes Layout der Basis-Packages am unteren Rand (<code>StandardizationTemplate</code>, <code>GenericStructure</code>, <code>FeatureModelTemplate</code>).\n</li></ul>"}, {"from": "FIG-216d8bb8228b7e97", "to": "FIG-f696b1aba3c07875", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Package <code>AdaptivePlatform</code> hinzugefügt.\n</li><li>Neue Import-Abhängigkeiten für <code>AdaptivePlatform</code>:\n<ul class=\"fig-list\"><li><code>AdaptivePlatform</code> importiert <code>SWComponentTemplate</code>.\n</li><li><code>AdaptivePlatform</code> importiert <code>EcuResourceTemplate</code>.\n</li><li><code>AdaptivePlatform</code> importiert <code>SystemTemplate</code>.\n</li></ul>\n</li></ul>"}, {"from": "FIG-f696b1aba3c07875", "to": "FIG-4e397706d674eae0", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4e397706d674eae0", "to": "FIG-48f991b2048a3033", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-48f991b2048a3033", "to": "FIG-f65f97fe60602feb", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Package <code>AbstractPlatform</code> hinzugefügt (unten links).\n</li><li>Neue Import-Abhängigkeit von <code>AbstractPlatform</code> auf <code>SWComponentTemplate</code>.\n</li></ul>"}]};
